#sales-stock-wrapper {
    font-family: Arial, sans-serif;
}

/* Loader */
#loader {
    text-align: center;
    padding: 20px;
    color: #666;
}

/* Table */
.sales-table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;
}

.sales-table th {
    background: #f7f7f7;
    padding: 10px;
    font-weight: 600;
