script:
setTimeout(() => {

    // =========================
    // TOP SELLING ITEMS
    // =========================
    frappe.call({
        method: "frappe.desk.query_report.run",
        args: {
            report_name: "Top Selling Items 1",
            filters: {
                from_date: frappe.datetime.add_months(frappe.datetime.get_today(), -1),
                to_date: frappe.datetime.get_today(),
                company: frappe.defaults.get_default("company")
            }
        },
        callback: function (r) {

            let container = root_element.querySelector("#top-selling-items");

            if (!container) return;

            container.innerHTML = "";

            let data = r.message.result || [];

            if (!data.length) {
                container.innerHTML = "<p>No data available</p>";
                return;
            }

            // DESCENDING SORT
            data.sort((a, b) => {

                let qtyA =
                    a.qty ||
                    a.stock_qty ||
                    a.total_qty ||
                    Object.values(a)[1] ||
                    0;

                let qtyB =
                    b.qty ||
                    b.stock_qty ||
                    b.total_qty ||
                    Object.values(b)[1] ||
                    0;

                return qtyB - qtyA;
            });

            data.slice(0, 5).forEach((row, index) => {

                let item =
                    row.item_name ||
                    row.item_code ||
                    row.item ||
                    Object.values(row)[0];

                let qty =
                    row.qty ||
                    row.stock_qty ||
                    row.total_qty ||
                    Object.values(row)[1] ||
                    0;

                container.insertAdjacentHTML("beforeend", `
                    <div class="tsi-row">
                        <div class="tsi-rank">${index + 1}.</div>
                        <div class="tsi-item">${item}</div>
                        <div class="tsi-qty">${qty}</div>
                    </div>
                `);
            });
        }
    });


    // =========================
    // LEAST SELLING ITEMS
    // =========================
    frappe.call({
        method: "frappe.desk.query_report.run",
        args: {
            report_name: "Least Selling Items",
            filters: {
                from_date: frappe.datetime.add_months(frappe.datetime.get_today(), -1),
                to_date: frappe.datetime.get_today(),
                company: frappe.defaults.get_default("company")
            }
        },
        callback: function (r) {

            let container = root_element.querySelector("#least-selling-items");

            if (!container) return;

            container.innerHTML = "";

            let data = r.message.result || [];

            if (!data.length) {
                container.innerHTML = "<p>No data available</p>";
                return;
            }

            // ASCENDING SORT
            data.sort((a, b) => {

                let qtyA =
                    a.qty ||
                    a.stock_qty ||
                    a.total_qty ||
                    Object.values(a)[1] ||
                    0;

                let qtyB =
                    b.qty ||
                    b.stock_qty ||
                    b.total_qty ||
                    Object.values(b)[1] ||
                    0;

                return qtyA - qtyB;
            });

            data.slice(0, 5).forEach((row, index) => {

                let item =
                    row.item_name ||
                    row.item_code ||
                    row.item ||
                    Object.values(row)[0];

                let qty =
                    row.qty ||
                    row.stock_qty ||
                    row.total_qty ||
                    Object.values(row)[1] ||
                    0;

                container.insertAdjacentHTML("beforeend", `
                    <div class="tsi-row">
                        <div class="tsi-rank">${index + 1}.</div>
                        <div class="tsi-item">${item}</div>
                        <div class="tsi-qty">${qty}</div>
                    </div>
                `);
            });
        }
    });

}, 500);

